window.AUTH=window.AUTH||{};window.AUTH["22-704"]={"d":"22-704","id":"2023/22-704","n":"Vidal v. Elster","briefs":[{"k":"petitioner","label":"Brief of petitioner Katherine K. Vidal, Under Secretary of Commerce Intellectual Property and Director, United States Patent and Trademark Office","date":"2023-07-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-704/272918/20230725195926740_22-704tsUnitedStates.pdf","side":"pet","n":62},{"k":"respondent","label":"Brief of respondent Steve Elster","date":"2023-09-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-704/278867/20230905184138600_Elster%20Merits%20Brief.pdf","side":"res","n":49},{"k":"reply","label":"Reply of petitioner Katherine K. Vidal, Under Secretary of Commerce Intellectual Property and Director, United States Patent and Trademark Office","date":"2023-10-05","url":"https://www.supremecourt.gov/DocketPDF/22/22-704/284317/20231005183512233_22-704%20Elster%20Reply.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r33_qqm4.pdf","tr":true,"items":[{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"by":{"0":"3, 39","1":"4, 5, 21"},"q":[{"src":"brief","b":0,"text":"[o]ne who first uses a distinct mark in commerce * * * acquires rights to that mark.","cite":"575 U.S. 138, 142"},{"src":"brief","b":0,"text":"prevent[] others from using the mark.","cite":"575 U.S. 138, 142"}]},{"t":"case","label":"Cardtoons, L.C. v. Major League Baseball Players Ass’n","cite":"95 F.3d 959","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/95/959/","by":{"0":"38","1":"31, 32"},"q":[{"src":"brief","b":1,"text":"the right of a person to control the commercial use of his or her identity.","cite":"95 F.3d 959, 967"}]},{"t":"case","label":"Christian Legal Soc’y Chapter of the Univ. of Cal., Hastings Coll. of the Law v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"by":{"0":"18, 19, 23, 27, 35","1":"37, 38, 39, 40, 41","2":"7, 9, 10, 15"},"q":[{"src":"brief","b":0,"text":"would, in practical effect, invalidate a defining characteristic of [such] forums—the State may ‘reserve them for certain groups.’","cite":"561 U.S. at 681"},{"src":"brief","b":1,"text":"taking into account the … forum’s function and all the surrounding circumstances,","cite":"561 U.S. 661, 685"},{"src":"brief","b":1,"text":"may not exclude speech where its distinction is not reasonable in light of the purpose served by the forum.","cite":"561 U.S. at 685"},{"src":"brief","b":2,"text":"is justified without reference to the * * * viewpoint","cite":"561 U.S. 661, 696"},{"src":"argument","who":"Justice Kagan","text":"It's not the -- it's not the register, it's not the book that's the forum, but the registration program is the forum, much like, in Christian Legal Society, the student activities program was the forum, a metaphorical forum, if -- if you will, but that's what we said in CLS."},{"src":"argument","who":"Justice Kagan","text":"I mean, I can cite Finley and Cornelius and Ysursa and Davenport and Regan and Christian Legal Society. All those cases are benefits cases where we've said, as long as it's not viewpoint-based, government can select, government can give the benefit to some and not the benefit to others."},{"src":"argument","who":"Mr. Taylor","text":"If you look at the opinions in Christian Legal Society on both sides, I don't think anyone on the Court thought that they -- they were engaging in rational basis review."}]},{"t":"case","label":"Comedy III Prods., Inc. v. Gary Saderup, Inc.","cite":"21 P.3d 797","y":2001,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/21/797/","by":{"0":"38"}},{"t":"case","label":"Cornelius v. NAACP Legal Def. & Educ. Fund, Inc.","cite":"473 U.S. 788","y":1985,"id":"1984/84-312","sc":1,"by":{"0":"19, 28, 30, 37, 38","1":"38, 41","2":"4, 18, 21, 22"},"q":[{"src":"brief","b":1,"text":"if he is not a member of the class of speakers for whose especial benefit the forum was created.","cite":"473 U.S. 788, 806"},{"src":"argument","who":"Mr. Stewart","text":"I think you could analogize this -- this program roughly to the union dues cases, to Cornelius, which involved access to the Combined Federal Campaign."},{"src":"argument","who":"Justice Kagan","text":"I mean, I can cite Finley and Cornelius and Ysursa and Davenport and Regan and Christian Legal Society. All those cases are benefits cases where we've said, as long as it's not viewpoint-based, government can select, government can give the benefit to some and not the benefit to others."}]},{"t":"case","label":"D.C. One Wholesaler, Inc. v. Chien","cite":"120 U.S.P.Q.2d 1710","y":2016,"court":"T.T.A.B. Nov. 9","url":"https://www.courtlistener.com/c/U.S.P.Q.2d/120/1710/","by":{"0":"26"}},{"t":"case","label":"Davenport v. Washington Educ. Ass’n","cite":"551 U.S. 177","y":2007,"id":"2006/05-1589","sc":1,"by":{"0":"9, 17, 20, 26, 37, 38","1":"43","2":"12, 13, 21"},"q":[{"src":"brief","b":0,"text":"will impermissibly interfere with the marketplace of ideas is sometimes attenuated.","cite":"551 U.S. 177, 188"},{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"`offcial suppression of ideas is afoot.'","cite":"551 U. S., at 189"},{"src":"opinion","who":"Justice Sotomayor, concurring in the judgment","text":"`there is no realistic possibility that offcial suppression of ideas is afoot.'","cite":"551 U. S. 177, 188–189"},{"src":"argument","who":"Mr. Stewart","text":"So it -- in -- in a very general way, it's providing the same type of assistance as in Ysursa, in Davenport, et cetera. It is making it easier for one private party to try to get money from other private parties."},{"src":"argument","who":"Justice Kagan","text":"I mean, I can cite Finley and Cornelius and Ysursa and Davenport and Regan and Christian Legal Society. All those cases are benefits cases where we've said, as long as it's not viewpoint-based, government can select, government can give the benefit to some and not the benefit to others."}]},{"t":"case","label":"ETW Corp. v. Jireh Publ’g, Inc.","cite":"332 F.3d 915","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/332/915/","by":{"0":"38","1":"32"},"q":[{"src":"brief","b":1,"text":"scrutiny and comment in the public media.","cite":"332 F.3d at 931"}]},{"t":"case","label":"Hamilton-Brown Shoe Co. v. Wolf Bros. & Co.","cite":"240 U.S. 251","y":1916,"id":"scdb/1915-097","sc":1,"by":{"0":"3"}},{"t":"case","label":"Hart v. Electronic Arts, Inc.","cite":"717 F.3d 141","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/717/141/","by":{"0":"38"}},{"t":"case","label":"Iancu v. Brunetti","cite":"139 S. Ct. 2294","y":2019,"id":"2018/18-302","sc":1,"by":{"0":"4, 8, 9, 11-15, 17, 21, 22, 24, 27-29, 31, 34-36, 39","1":"5, 6, 18, 20, 25, 40, 42","2":"1, 4, 5, 10, 15, 18, 19, 22"},"q":[{"src":"brief","b":0,"text":"administers a federal registration system for trademarks.","cite":"139 S. Ct. 2294, 2297"},{"src":"brief","b":0,"text":"which forecloses some defenses in infringement actions,","cite":"139 S. Ct. at 2298"},{"src":"brief","b":1,"text":"on its face disfavor some ideas,","cite":"139 S. Ct. at 2301"},{"src":"brief","b":2,"text":"[n]o speech is being restricted; no one is being punished.","cite":"139 S. Ct. at 2303"},{"src":"brief","b":2,"text":"refrain[] from lending [the government’s] ancillary support to","cite":"139 S. Ct. at 2317"}]},{"t":"case","label":"Jack Daniel’s Props., Inc. v. VIP Prods. LLC","cite":"143 S. Ct. 1578","y":2023,"id":"2022/22-148","sc":1,"by":{"0":"3-5, 24-26, 32","2":"10"},"q":[{"src":"brief","b":0,"text":"‘to identify the origin or ownership of the article to which it is affixed.’","cite":"143 S. Ct. 1578, 1583"},{"src":"brief","b":0,"text":"certain benefits, useful in infringement litigation,","cite":"143 S. Ct. 1578, 1584"},{"src":"argument","who":"Mr. Stewart","text":"And I'd point the Court's to -- to its decision last term in Jack Daniels as well. That is, the Court decided some legal issues, and it remanded for the lower courts to perform a likelihood-of-confusion analysis."},{"src":"argument","who":"Mr. Taylor","text":"So you're -- you're absolutely right, Justice Jackson, that the purpose of trademark law in general and the purpose of the registration system, as the -- the opinion of the Court in the Jack Daniel's case from earlier this year makes clear, is to ensure that marks function as -- as trademarks, that is, that they function as source identifiers, and they don't -- they're not likely to confuse or mislead consumers as to the source."},{"src":"argument","who":"Mr. Taylor","text":"And so I understood my friend in his responses to your question, Justice Barrett, to -- to effectively concede that the reason why, if the PTO were to register this mark, had the former president sought registration of it, the reason why that wouldn't give rise to First Amendment concerns is because of what this Court said in Jack Daniel's, which is that the First Amendment and trademark law, when it sticks to its historical function, they play well together."}]},{"t":"case","label":"John Anthony, Inc. v. Fashions by John Anthony, Inc.","cite":"209 U.S.P.Q. 517","y":1980,"court":"T.T.A.B. Dec. 30","url":"https://www.courtlistener.com/c/U.S.P.Q./209/517/","by":{"0":"28"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"485 U.S. 176","y":1988,"id":"1987/86-495","sc":1,"by":{"0":"3, 25, 39"}},{"t":"case","label":"Lohan v. Take-Two Interactive Software, Inc.","cite":"97 N.E.3d 389","y":2018,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.3d/97/389/","by":{"0":"38"}},{"t":"case","label":"Maher v. Roe","cite":"432 U.S. 464","y":1977,"id":"1976/75-1440","sc":1,"by":{"0":"17"}},{"t":"case","label":"Martin v. Carter Hawley Hale Stores, Inc.","cite":"206 U.S.P.Q. 931","y":1979,"court":"T.T.A.B. Dec. 12","url":"https://www.courtlistener.com/c/U.S.P.Q./206/931/","by":{"0":"14, 29"},"q":[{"src":"brief","b":0,"text":"whether the mark would be recognized and understood by the public as identifying the person.","cite":"206 U.S.P.Q. 931, 1979"}]},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"by":{"0":"3, 8, 11-13, 21, 30","1":"3, 4, 5, 6, 7, 13, 14, 15, 17, 18, 20, 22, 23, 24, 25, 27, 33, 38, 42, 43","2":"1"},"q":[{"src":"brief","b":0,"text":"[t]rademarks are private, not government, speech.","cite":"582 U.S. at 239"},{"src":"brief","b":1,"text":"far … more than identify a good or service.","cite":"582 U.S. at 224"},{"src":"brief","b":1,"text":"The foundation of current federal trademark law is the Lanham Act.","cite":"582 U.S. at 224"},{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"helps to ensure that trademarks are fully protected.","cite":"582 U. S., at 225"},{"src":"opinion","who":"Justice Sotomayor, concurring in the judgment","text":"framework `for deciding free speech challenges to provisions of the Lanham Act.'","cite":"582 U. S., at 245, n. 17"},{"src":"argument","who":"Justice Alito","text":"I said what I think about the government benefits theory in Matal versus Tam, so there's no secret about that. And if your argument require -- if -- if I could not vote to sustain this without saying this is the attachment of a condition to a government benefit or that it's analogous to the attachment of a condition to a government benefit, I -- I mean, you don't need my vote to win your case. (Laughter.)"}]},{"t":"case","label":"Moseley v. V Secret Catalogue, Inc.","cite":"537 U.S. 418","y":2003,"id":"2002/01-1015","sc":1,"by":{"0":"3"},"q":[{"src":"brief","b":0,"text":"Infringement law protects consumers from being misled by the use of infringing marks and also protects producers from unfair practices by an imitating competitor.","cite":"537 U.S. 418, 428"}]},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"by":{"0":"17"}},{"t":"case","label":"Paulsen v. Personality Posters, Inc.","cite":"299 N.Y.S.2d 501","y":1968,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/299/501/","by":{"0":"38"}},{"t":"case","label":"Perry Educ. Ass’n v. Perry Local Educators’ Ass’n","cite":"460 U.S. 37","y":1983,"id":"1982/81-896","sc":1,"by":{"0":"19, 27, 28","2":"13, 14"},"q":[{"src":"brief","b":0,"text":"[i]mplicit in the concept of the nonpublic forum,","cite":"460 U.S. at 49"},{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"cbomlpiactiabletiwoitnh the intended purpose of the property.","cite":"460 U. S. 37, 49"}]},{"t":"case","label":"Pleasant Grove City v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"a government entity may create a forum that is limited to use by certain groups or dedicated solely to the discussion of certain subjects.","cite":"555 U.S. 460, 470"}]},{"t":"case","label":"Reed v. Town of Gilbert","cite":"576 U.S. 155","y":2015,"id":"2014/13-502","sc":1,"by":{"0":"17","1":"19, 24, 26, 28, 40","2":"13"},"q":[{"src":"brief","b":1,"text":"defin[es] regulated speech by particular subject matter,","cite":"576 U.S. 155, 163"},{"src":"brief","b":1,"text":"evidence of an improper censorial motive","cite":"576 U.S. at 165"}]},{"t":"case","label":"Regan v. Taxation With Representation of Wash.","cite":"461 U.S. 540","y":1983,"id":"1982/81-2338","sc":1,"by":{"0":"17, 18, 24, 28, 37, 38","1":"37","2":"4, 5, 18, 21"},"q":[{"src":"brief","b":0,"text":"a legislature’s decision not to subsidize the exercise of a fundamental right * * * is not subject to strict scrutiny,","cite":"461 U.S. at 549"},{"src":"brief","b":0,"text":"Congress has not infringed any First Amendment rights or regulated any First Amendment activity.","cite":"461 U.S. at 546"},{"src":"argument","who":"Justice Kagan","text":"I mean, I can cite Finley and Cornelius and Ysursa and Davenport and Regan and Christian Legal Society. All those cases are benefits cases where we've said, as long as it's not viewpoint-based, government can select, government can give the benefit to some and not the benefit to others."}]},{"t":"case","label":"Rosenberger v. Rector & Visitors of Univ. of Va.","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"by":{"0":"19, 35","1":"40"},"q":[{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"reserv[e the property] for certain groups or for the discussion of certain topics.","cite":"515 U. S. 819, 829"},{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"respect[s] the lawful boundaries it has itself set.","cite":"515 U. S., at 829"}]},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"by":{"0":"17, 18, 23, 38","2":"5, 15, 21"},"q":[{"src":"brief","b":0,"text":"refusal to fund protected activity, without more, cannot be equated with the imposition of a ‘penalty’ on that activity,","cite":"500 U.S. at 193"},{"src":"brief","b":2,"text":"The Government has no constitutional duty to subsidize an activity merely because the activity is constitutionally protected.","cite":"500 U.S. at 201"}]},{"t":"case","label":"San Francisco Arts & Athletics, Inc. v. United States Olympic Comm.","cite":"483 U.S. 522","y":1987,"id":"1986/86-270","sc":1,"by":{"0":"25, 26"},"q":[{"src":"argument","who":"Justice Alito","text":"Stewart, do you think that the constitutionality of this provision could be sustained on a theory similar to the one in San Francisco Arts and Athletics versus U.S."},{"src":"argument","who":"Mr. Stewart","text":"But the -- the other difference is that in San Francisco -- in the San Francisco case, what you were dealing with was the -- the actual imposition of a restriction on speech."}]},{"t":"case","label":"Titan Sports, Inc v. Comics World Corp.","cite":"870 F.2d 85","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/870/85/","by":{"0":"38"}},{"t":"case","label":"United States v. American Library Ass’n","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"by":{"0":"28"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Samara Bros.","cite":"529 U.S. 205","y":2000,"id":"1999/99-150","sc":1,"by":{"0":"3"}},{"t":"case","label":"Ysursa v. Pocatello Educ. Ass’n","cite":"555 U.S. 353","y":2009,"id":"2008/07-869","sc":1,"by":{"0":"16, 17, 20, 21, 23, 28, 30, 35, 37, 38","1":"37","2":"2, 4, 13, 15, 18, 21, 22"},"q":[{"src":"brief","b":0,"text":"the statute, rather than suppressing union speech, simply declined to assist that speech by granting the unions the right to charge agency fees for election activities.","cite":"555 U.S. at 361"},{"src":"brief","b":0,"text":"[t]he First Amendment prohibits government from ‘abridging the freedom of speech.’","cite":"555 U.S. at 355"},{"src":"argument","who":"Mr. Stewart","text":"So it -- in -- in a very general way, it's providing the same type of assistance as in Ysursa, in Davenport, et cetera. It is making it easier for one private party to try to get money from other private parties."},{"src":"argument","who":"Justice Kagan","text":"I mean, I can cite Finley and Cornelius and Ysursa and Davenport and Regan and Christian Legal Society. All those cases are benefits cases where we've said, as long as it's not viewpoint-based, government can select, government can give the benefit to some and not the benefit to others."}]},{"t":"const","label":"Amendment I","clauses":[["free-speech","Free Speech Clause"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"2, 7-13, 15-20, 24, 25, 27, 33-40","2":"2, 4, 5, 8, 12, 16, 18, 20-22"}},{"t":"usc","label":"15 U.S.C. § 1051","url":"https://www.law.cornell.edu/uscode/text/15/1051","subs":["(a)(1)","(a)(2)","(b)","(b)(1)","(b)(2)","(a)(3)","(b)(3)","(d)(1)"],"stext":{"head":"§1051. Application for registration; verification","paras":[[0,"(a) Application for use of trademark"],[0,"(1) The owner of a trademark used in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director, and such number of specimens or facsimiles of the mark as used as may be required by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the date of the applicant's first use of the mark, the date of the applicant's first use of the mark in commerce, the goods in connection with which the mark is used, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify that—"],[1,"(A) the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be the owner of the mark sought to be registered;"],[1,"(B) to the best of the verifier's knowledge and belief, the facts recited in the application are accurate;"],[1,"(C) the mark is in use in commerce; and"],[1,"(D) to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive, except that, in the case of every application claiming concurrent use, the applicant shall—"],[2,"(i) state exceptions to the claim of exclusive use; and"],[2,"(ii) shall 1 specify, to the extent of the verifier's knowledge—"],[3,"(I) any concurrent use by others;"],[3,"(II) the goods on or in connection with which and the areas in which each concurrent use exists;"],[3,"(III) the periods of each use; and"],[3,"(IV) the goods and area for which the applicant desires registration."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(b) Application for bona fide intention to use trademark"],[0,"(1) A person who has a bona fide intention, under circumstances showing the good faith of such person, to use a trademark in commerce may request registration of its trademark on the principal register hereby established by paying the prescribed fee and filing in the Patent and Trademark Office an application and a verified statement, in such form as may be prescribed by the Director."],[0,"(2) The application shall include specification of the applicant's domicile and citizenship, the goods in connection with which the applicant has a bona fide intention to use the mark, and a drawing of the mark."],[0,"(3) The statement shall be verified by the applicant and specify—"],[1,"(A) that the person making the verification believes that he or she, or the juristic person in whose behalf he or she makes the verification, to be entitled to use the mark in commerce;"],[1,"(B) the applicant's bona fide intention to use the mark in commerce;"],[1,"(C) that, to the best of the verifier's knowledge and belief, the facts recited in the application are accurate; and"],[1,"(D) that, to the best of the verifier's knowledge and belief, no other person has the right to use such mark in commerce either in the identical form thereof or in such near resemblance thereto as to be likely, when used on or in connection with the goods of such other person, to cause confusion, or to cause mistake, or to deceive."],[0,"Except for applications filed pursuant to section 1126 of this title, no mark shall be registered until the applicant has met the requirements of subsections (c) and (d) of this section."],[0,"(4) The applicant shall comply with such rules or regulations as may be prescribed by the Director. The Director shall promulgate rules prescribing the requirements for the application and for obtaining a filing date herein."],[0,"(c) Amendment of application under subsection (b) to conform to requirements of subsection (a)"],[0,"At any time during examination of an application filed under subsection (b), an applicant who has made use of the mark in commerce may claim the benefits of such use for purposes of this chapter, by amending his or her application to bring it into conformity with the requirements of subsection (a)."],[0,"(d) Verified statement that trademark is used in commerce"],[0,"(1) Within six months after the date on which the notice of allowance with respect to a mark is issued under section 1063(b)(2) of this title to an applicant under subsection (b) of this section, the applicant shall file in the Patent and Trademark Office, together with such number of specimens or facsimiles of the mark as used in commerce as may be required by the Director and payment of the prescribed fee, a verified statement that the mark is in use in commerce and specifying the date of the applicant's first use of the mark in commerce and those goods or services specified in the notice of allowance on or in connection with which the mark is used in commerce. Subject to examination and acceptance of the statement of use, the mark shall be registered in the Patent and Trademark Office, a certificate of registration shall be issued for those goods or services recited in the statement of use for which the mark is entitled to registration, and notice of registration shall be published in the Official Gazette of the Patent and Trademark Office. Such examination may include an examination of the factors set forth in subsections (a) through (e) of section 1052 of this title. The notice of registration shall specify the goods or services for which the mark is registered."],[0,"(2) The Director shall extend, for one additional 6-month period, the time for filing the statement of use under paragraph (1), upon written request of the applicant before the expiration of the 6-month period provided in paragraph (1). In addition to an extension under the preceding sentence, the Director may, upon a showing of good cause by the applicant, further extend the time for filing the statement of use under paragraph (1) for periods aggregating not more than 24 months, pursuant to written request of the applicant made before the expiration of the last extension granted under this paragraph. Any request for an extension under this paragraph shall be accompanied by a verified statement that the applicant has a continued bona fide intention to use the mark in commerce and specifying those goods or services identified in the notice of allowance on or in connection with which the applicant has a continued bona fide intention to use the mark in commerce. Any request for an extension under this paragraph shall be accompanied by payment of the prescribed fee. The Director shall issue regulations setting forth guidelines for determining what constitutes good cause for purposes of this paragraph."],[0,"(3) The Director shall notify any applicant who files a statement of use of the acceptance or refusal thereof and, if the statement of use is refused, the reasons for the refusal. An applicant may amend the statement of use."],[0,"(4) The failure to timely file a verified statement of use under paragraph (1) or an extension request under paragraph (2) shall result in abandonment of the application, unless it can be shown to the satisfaction of the Director that the delay in responding was unintentional, in which case the time for filing may be extended, but for a period not to exceed the period specified in paragraphs (1) and (2) for filing a statement of use."],[0,"(e) Designation of resident for service of process and notices"],[0,"If the applicant is not domiciled in the United States the applicant may designate, by a document filed in the United States Patent and Trademark Office, the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark. Such notices or process may be served upon the person so designated by leaving with that person or mailing to that person a copy thereof at the address specified in the last designation so filed. If the person so designated cannot be found at the address given in the last designation, or if the registrant does not designate by a document filed in the United States Patent and Trademark Office the name and address of a person resident in the United States on whom may be served notices or process in proceedings affecting the mark, such notices or process may be served on the Director."],[0,"(f) Third-party submission of evidence"],[0,"A third party may submit for consideration for inclusion in the record of an application evidence relevant to a ground for refusal of registration. The third-party submission shall identify the ground for refusal and include a concise description of each piece of evidence submitted in support of each identified ground for refusal. Not later than 2 months after the date on which the submission is filed, the Director shall determine whether the evidence should be included in the record of the application. The Director shall establish by regulation appropriate procedures for the consideration of evidence submitted by a third party under this subsection and may prescribe a fee to accompany the submission. If the Director determines that the third-party evidence should be included in the record of the application, only the evidence and the ground for refusal to which the evidence relates may be so included. Any determination by the Director whether or not to include evidence in the record of an application shall be final and non-reviewable, and a determination to include or to not include evidence in the record shall not prejudice any party's right to raise any issue and rely on any evidence in any other proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1051?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 2, 27, 2, 27, 2, 27, 2, 27, 2, 27","2":"3, 6, 6, 6, 6, 6, 6"},"q":[{"src":"brief","b":0,"text":"the goods in connection with which the mark is used","cite":"15 U.S.C. 1051(a)(2)"},{"src":"brief","b":2,"text":"denying registration to an otherwise valid mark used in commerce deprives companies of this notice-giving function, and thus invites infringement and source confusion.","cite":"15 U.S.C. 1051"},{"src":"brief","b":2,"text":"specimens or facsimiles of the mark as used,","cite":"15 U.S.C. 1051(a)(1)"}]},{"t":"usc","label":"15 U.S.C. § 1052","url":"https://www.law.cornell.edu/uscode/text/15/1052","subs":["(a)","(b)","(c)","(d)","(e)","(e)(1)"],"stext":{"head":"§1052. Trademarks registrable on principal register; concurrent registration","paras":[[0,"No trademark by which the goods of the applicant may be distinguished from the goods of others shall be refused registration on the principal register on account of its nature unless it—"],[0,"(a) Consists of or comprises immoral, deceptive, or scandalous matter; or matter which may disparage or falsely suggest a connection with persons, living or dead, institutions, beliefs, or national symbols, or bring them into contempt, or disrepute; or a geographical indication which, when used on or in connection with wines or spirits, identifies a place other than the origin of the goods and is first used on or in connection with wines or spirits by the applicant on or after one year after the date on which the WTO Agreement (as defined in section 3501(9) of title 19) enters into force with respect to the United States."],[0,"(b) Consists of or comprises the flag or coat of arms or other insignia of the United States, or of any State or municipality, or of any foreign nation, or any simulation thereof."],[0,"(c) Consists of or comprises a name, portrait, or signature identifying a particular living individual except by his written consent, or the name, signature, or portrait of a deceased President of the United States during the life of his widow, if any, except by the written consent of the widow."],[0,"(d) Consists of or comprises a mark which so resembles a mark registered in the Patent and Trademark Office, or a mark or trade name previously used in the United States by another and not abandoned, as to be likely, when used on or in connection with the goods of the applicant, to cause confusion, or to cause mistake, or to deceive: Provided, That if the Director determines that confusion, mistake, or deception is not likely to result from the continued use by more than one person of the same or similar marks under conditions and limitations as to the mode or place of use of the marks or the goods on or in connection with which such marks are used, concurrent registrations may be issued to such persons when they have become entitled to use such marks as a result of their concurrent lawful use in commerce prior to (1) the earliest of the filing dates of the applications pending or of any registration issued under this chapter; (2) July 5, 1947, in the case of registrations previously issued under the Act of March 3, 1881, or February 20, 1905, and continuing in full force and effect on that date; or (3) July 5, 1947, in the case of applications filed under the Act of February 20, 1905, and registered after July 5, 1947. Use prior to the filing date of any pending application or a registration shall not be required when the owner of such application or registration consents to the grant of a concurrent registration to the applicant. Concurrent registrations may also be issued by the Director when a court of competent jurisdiction has finally determined that more than one person is entitled to use the same or similar marks in commerce. In issuing concurrent registrations, the Director shall prescribe conditions and limitations as to the mode or place of use of the mark or the goods on or in connection with which such mark is registered to the respective persons."],[0,"(e) Consists of a mark which (1) when used on or in connection with the goods of the applicant is merely descriptive or deceptively misdescriptive of them, (2) when used on or in connection with the goods of the applicant is primarily geographically descriptive of them, except as indications of regional origin may be registrable under section 1054 of this title, (3) when used on or in connection with the goods of the applicant is primarily geographically deceptively misdescriptive of them, (4) is primarily merely a surname, or (5) comprises any matter that, as a whole, is functional."],[0,"(f) Except as expressly excluded in subsections (a), (b), (c), (d), (e)(3), and (e)(5) of this section, nothing in this chapter shall prevent the registration of a mark used by the applicant which has become distinctive of the applicant's goods in commerce. The Director may accept as prima facie evidence that the mark has become distinctive, as used on or in connection with the applicant's goods in commerce, proof of substantially exclusive and continuous use thereof as a mark by the applicant in commerce for the five years before the date on which the claim of distinctiveness is made. Nothing in this section shall prevent the registration of a mark which, when used on or in connection with the goods of the applicant, is primarily geographically deceptively misdescriptive of them, and which became distinctive of the applicant's goods in commerce before December 8, 1993."],[0,"A mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be refused registration only pursuant to a proceeding brought under section 1063 of this title. A registration for a mark which would be likely to cause dilution by blurring or dilution by tarnishment under section 1125(c) of this title, may be canceled pursuant to a proceeding brought under either section 1064 of this title or section 1092 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1052?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 27, 5, 6, 8, 12, 13, 27, 32, 33, 30, 30, 30, 30, 30","2":"6, 12, 10, 22, 1, 6-8"},"q":[{"src":"brief","b":0,"text":"a name, portrait, or signature identifying a particular living individual except by his written consent.","cite":"15 U.S.C. 1052(c)"},{"src":"brief","b":0,"text":"identifying * * * particular living individual[s],","cite":"15 U.S.C. 1052(c)"},{"src":"brief","b":2,"text":"[c]onsists of or comprises a name * * * identifying a particular living individual except by his written consent.","cite":"15 U.S.C. 1052(c)"}]},{"t":"usc","label":"15 U.S.C. § 1057","url":"https://www.law.cornell.edu/uscode/text/15/1057","subs":["(a)","(b)"],"stext":{"head":"§1057. Certificates of registration","paras":[[0,"(a) Issuance and form"],[0,"Certificates of registration of marks registered upon the principal register shall be issued in the name of the United States of America, under the seal of the United States Patent and Trademark Office, and shall be signed by the Director or have his signature placed thereon, and a record thereof shall be kept in the United States Patent and Trademark Office. The registration shall reproduce the mark, and state that the mark is registered on the principal register under this chapter, the date of the first use of the mark, the date of the first use of the mark in commerce, the particular goods or services for which it is registered, the number and date of the registration, the term thereof, the date on which the application for registration was received in the United States Patent and Trademark Office, and any conditions and limitations that may be imposed in the registration."],[0,"(b) Certificate as prima facie evidence"],[0,"A certificate of registration of a mark upon the principal register provided by this chapter shall be prima facie evidence of the validity of the registered mark and of the registration of the mark, of the owner's ownership of the mark, and of the owner's exclusive right to use the registered mark in commerce on or in connection with the goods or services specified in the certificate, subject to any conditions or limitations stated in the certificate."],[0,"(c) Application to register mark considered constructive use"],[0,"Contingent on the registration of a mark on the principal register provided by this chapter, the filing of the application to register such mark shall constitute constructive use of the mark, conferring a right of priority, nationwide in effect, on or in connection with the goods or services specified in the registration against any other person except for a person whose mark has not been abandoned and who, prior to such filing—"],[1,"(1) has used the mark;"],[1,"(2) has filed an application to register the mark which is pending or has resulted in registration of the mark; or"],[1,"(3) has filed a foreign application to register the mark on the basis of which he or she has acquired a right of priority, and timely files an application under section 1126(d) of this title to register the mark which is pending or has resulted in registration of the mark."],[0,"(d) Issuance to assignee"],[0,"A certificate of registration of a mark may be issued to the assignee of the applicant, but the assignment must first be recorded in the United States Patent and Trademark Office. In case of change of ownership the Director shall, at the request of the owner and upon a proper showing and the payment of the prescribed fee, issue to such assignee a new certificate of registration of the said mark in the name of such assignee, and for the unexpired part of the original period."],[0,"(e) Surrender, cancellation, or amendment by owner"],[0,"Upon application of the owner the Director may permit any registration to be surrendered for cancellation, and upon cancellation appropriate entry shall be made in the records of the United States Patent and Trademark Office. Upon application of the owner and payment of the prescribed fee, the Director for good cause may permit any registration to be amended or to be disclaimed in part: Provided, That the amendment or disclaimer does not alter materially the character of the mark. Appropriate entry shall be made in the records of the United States Patent and Trademark Office and upon the certificate of registration."],[0,"(f) Copies of United States Patent and Trademark Office records as evidence"],[0,"Copies of any records, books, papers, or drawings belonging to the United States Patent and Trademark Office relating to marks, and copies of registrations, when authenticated by the seal of the United States Patent and Trademark Office and certified by the Director, or in his name by an employee of the Office duly designated by the Director, shall be evidence in all cases wherein the originals would be evidence; and any person making application therefor and paying the prescribed fee shall have such copies."],[0,"(g) Correction of United States Patent and Trademark Office mistake"],[0,"Whenever a material mistake in a registration, incurred through the fault of the United States Patent and Trademark Office, is clearly disclosed by the records of the Office a certificate stating the fact and nature of such mistake shall be issued without charge and recorded and a printed copy thereof shall be attached to each printed copy of the registration and such corrected registration shall thereafter have the same effect as if the same had been originally issued in such corrected form, or in the discretion of the Director a new certificate of registration may be issued without charge. All certificates of correction heretofore issued in accordance with the rules of the United States Patent and Trademark Office and the registrations to which they are attached shall have the same force and effect as if such certificates and their issue had been specifically authorized by statute."],[0,"(h) Correction of applicant's mistake"],[0,"Whenever a mistake has been made in a registration and a showing has been made that such mistake occurred in good faith through the fault of the applicant, the Director is authorized to issue a certificate of correction or, in his discretion, a new certificate upon the payment of the prescribed fee: Provided, That the correction does not involve such changes in the registration as to require republication of the mark."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1057?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30, 30"},"q":[{"src":"brief","b":0,"text":"in the name of the United States of America.","cite":"15 U.S.C. 1057(a)"},{"src":"brief","b":0,"text":"in the name of the United States,","cite":"15 U.S.C. 1057(a)"}]},{"t":"usc","label":"15 U.S.C. § 1062","url":"https://www.law.cornell.edu/uscode/text/15/1062","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 1072","url":"https://www.law.cornell.edu/uscode/text/15/1072","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"constructive notice of the registrant’s claim of ownership,","cite":"15 U.S.C. 1072"}]},{"t":"usc","label":"15 U.S.C. § 1091","url":"https://www.law.cornell.edu/uscode/text/15/1091","by":{"0":"30"}},{"t":"usc","label":"15 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/15/1111","stext":{"head":"§1111. Notice of registration; display with mark; recovery of profits and damages in infringement suit","paras":[[0,"Notwithstanding the provisions of section 1072 of this title, a registrant of a mark registered in the Patent and Trademark Office, may give notice that his mark is registered by displaying with the mark the words \"Registered in U.S. Patent and Trademark Office\" or \"Reg. U.S. Pat. & Tm. Off.\" or the letter R enclosed within a circle, thus ®; and in any suit for infringement under this chapter by such a registrant failing to give such notice of registration, no profits and no damages shall be recovered under the provisions of this chapter unless the defendant had actual notice of the registration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1111?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3"},"q":[{"src":"brief","b":0,"text":"may give notice that his mark is registered by displaying with the mark the words ‘Registered in U.S. Patent and Trademark Office’ or ‘Reg. U.S. Pat. & Tm. Off.’ or the letter R enclosed within a circle, thus ®.","cite":"15 U.S.C. 1111"},{"src":"brief","b":0,"text":"the words ‘Registered in U.S. Patent and Trademark Office’ or ‘Reg. U.S. Pat. & Tm. Off.’","cite":"15 U.S.C. 1111"}]},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)(a)","(1)"],"stext":{"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","paras":[[0,"(1) Any person who shall, without the consent of the registrant—"],[1,"(a) use in commerce any reproduction, counterfeit, copy, or colorable imitation of a registered mark in connection with the sale, offering for sale, distribution, or advertising of any goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive; or"],[1,"(b) reproduce, counterfeit, copy, or colorably imitate a registered mark and apply such reproduction, counterfeit, copy, or colorable imitation to labels, signs, prints, packages, wrappers, receptacles or advertisements intended to be used in commerce upon or in connection with the sale, offering for sale, distribution, or advertising of goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive,"],[0,"shall be liable in a civil action by the registrant for the remedies hereinafter provided. Under subsection (b) hereof, the registrant shall not be entitled to recover profits or damages unless the acts have been committed with knowledge that such imitation is intended to be used to cause confusion, or to cause mistake, or to deceive."],[0,"As used in this paragraph, the term \"any person\" includes the United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, or other persons acting for the United States and with the authorization and consent of the United States, and any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. The United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, other persons acting for the United States and with the authorization and consent of the United States, and any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(2) Notwithstanding any other provision of this chapter, the remedies given to the owner of a right infringed under this chapter or to a person bringing an action under section 1125(a) or (d) of this title shall be limited as follows:"],[1,"(A) Where an infringer or violator is engaged solely in the business of printing the mark or violating matter for others and establishes that he or she was an innocent infringer or innocent violator, the owner of the right infringed or person bringing the action under section 1125(a) of this title shall be entitled as against such infringer or violator only to an injunction against future printing."],[1,"(B) Where the infringement or violation complained of is contained in or is part of paid advertising matter in a newspaper, magazine, or other similar periodical or in an electronic communication as defined in section 2510(12) of title 18, the remedies of the owner of the right infringed or person bringing the action under section 1125(a) of this title as against the publisher or distributor of such newspaper, magazine, or other similar periodical or electronic communication shall be limited to an injunction against the presentation of such advertising matter in future issues of such newspapers, magazines, or other similar periodicals or in future transmissions of such electronic communications. The limitations of this subparagraph shall apply only to innocent infringers and innocent violators."],[1,"(C) Injunctive relief shall not be available to the owner of the right infringed or person bringing the action under section 1125(a) of this title with respect to an issue of a newspaper, magazine, or other similar periodical or an electronic communication containing infringing matter or violating matter where restraining the dissemination of such infringing matter or violating matter in any particular issue of such periodical or in an electronic communication would delay the delivery of such issue or transmission of such electronic communication after the regular time for such delivery or transmission, and such delay would be due to the method by which publication and distribution of such periodical or transmission of such electronic communication is customarily conducted in accordance with sound business practice, and not due to any method or device adopted to evade this section or to prevent or delay the issuance of an injunction or restraining order with respect to such infringing matter or violating matter."],[1,"(D)(i)(I) A domain name registrar, a domain name registry, or other domain name registration authority that takes any action described under clause (ii) affecting a domain name shall not be liable for monetary relief or, except as provided in subclause (II), for injunctive relief, to any person for such action, regardless of whether the domain name is finally determined to infringe or dilute the mark."],[1,"(II) A domain name registrar, domain name registry, or other domain name registration authority described in subclause (I) may be subject to injunctive relief only if such registrar, registry, or other registration authority has—"],[2,"(aa) not expeditiously deposited with a court, in which an action has been filed regarding the disposition of the domain name, documents sufficient for the court to establish the court's control and authority regarding the disposition of the registration and use of the domain name;"],[2,"(bb) transferred, suspended, or otherwise modified the domain name during the pendency of the action, except upon order of the court; or"],[2,"(cc) willfully failed to comply with any such court order."],[1,"(ii) An action referred to under clause (i)(I) is any action of refusing to register, removing from registration, transferring, temporarily disabling, or permanently canceling a domain name—"],[2,"(I) in compliance with a court order under section 1125(d) of this title; or"],[2,"(II) in the implementation of a reasonable policy by such registrar, registry, or authority prohibiting the registration of a domain name that is identical to, confusingly similar to, or dilutive of another's mark."],[1,"(iii) A domain name registrar, a domain name registry, or other domain name registration authority shall not be liable for damages under this section for the registration or maintenance of a domain name for another absent a showing of bad faith intent to profit from such registration or maintenance of the domain name."],[1,"(iv) If a registrar, registry, or other registration authority takes an action described under clause (ii) based on a knowing and material misrepresentation by any other person that a domain name is identical to, confusingly similar to, or dilutive of a mark, the person making the knowing and material misrepresentation shall be liable for any damages, including costs and attorney's fees, incurred by the domain name registrant as a result of such action. The court may also grant injunctive relief to the domain name registrant, including the reactivation of the domain name or the transfer of the domain name to the domain name registrant."],[1,"(v) A domain name registrant whose domain name has been suspended, disabled, or transferred under a policy described under clause (ii)(II) may, upon notice to the mark owner, file a civil action to establish that the registration or use of the domain name by such registrant is not unlawful under this chapter. The court may grant injunctive relief to the domain name registrant, including the reactivation of the domain name or transfer of the domain name to the domain name registrant."],[1,"(E) As used in this paragraph—"],[2,"(i) the term \"violator\" means a person who violates section 1125(a) of this title; and"],[2,"(ii) the term \"violating matter\" means matter that is the subject of a violation under section 1125(a) of this title."],[0,"(3)(A) Any person who engages in the conduct described in paragraph (11) of section 110 of title 17 and who complies with the requirements set forth in that paragraph is not liable on account of such conduct for a violation of any right under this chapter. This subparagraph does not preclude liability, nor shall it be construed to restrict the defenses or limitations on rights granted under this chapter, of a person for conduct not described in paragraph (11) of section 110 of title 17, even if that person also engages in conduct described in paragraph (11) of section 110 of such title."],[0,"(B) A manufacturer, licensee, or licensor of technology that enables the making of limited portions of audio or video content of a motion picture imperceptible as described in subparagraph (A) is not liable on account of such manufacture or license for a violation of any right under this chapter, if such manufacturer, licensee, or licensor ensures that the technology provides a clear and conspicuous notice at the beginning of each performance that the performance of the motion picture is altered from the performance intended by the director or copyright holder of the motion picture. The limitations on liability in subparagraph (A) and this subparagraph shall not apply to a manufacturer, licensee, or licensor of technology that fails to comply with this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1114?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","2":"11"},"q":[{"src":"brief","b":2,"text":"without the consent of the registrant.","cite":"15 U.S.C. 1114(1)"}]},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(a)","(b)"],"by":{"0":"3, 3"},"q":[{"src":"brief","b":0,"text":"of the registrant’s ownership of the mark, and of the registrant’s exclusive right to use the registered mark in commerce.","cite":"15 U.S.C. 1115(a)"},{"src":"brief","b":0,"text":"exclusive right to use the registered mark in commerce,","cite":"15 U.S.C. 1115(a)"}]},{"t":"usc","label":"15 U.S.C. § 1124","url":"https://www.law.cornell.edu/uscode/text/15/1124","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)"],"by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/15/1127","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"those manufactured or sold by others and to indicate the source of the goods.","cite":"15 U.S.C. 1127"}]},{"t":"usc","label":"15 U.S.C. § 1141b","url":"https://www.law.cornell.edu/uscode/text/15/1141b","by":{"0":"30"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(a)(1)"],"stext":{"head":"§2. Powers and duties","paras":[[0,"(a) In General.—The United States Patent and Trademark Office, subject to the policy direction of the Secretary of Commerce—"],[1,"(1) shall be responsible for the granting and issuing of patents and the registration of trademarks; and"],[1,"(2) shall be responsible for disseminating to the public information with respect to patents and trademarks."],[0,"(b) Specific Powers.—The Office—"],[1,"(1) shall adopt and use a seal of the Office, which shall be judicially noticed and with which letters patent, certificates of trademark registrations, and papers issued by the Office shall be authenticated;"],[1,"(2) may establish regulations, not inconsistent with law, which—"],[2,"(A) shall govern the conduct of proceedings in the Office;"],[2,"(B) shall be made in accordance with section 553 of title 5;"],[2,"(C) shall facilitate and expedite the processing of patent applications, particularly those which can be filed, stored, processed, searched, and retrieved electronically, subject to the provisions of section 122 relating to the confidential status of applications;"],[2,"(D) may govern the recognition and conduct of agents, attorneys, or other persons representing applicants or other parties before the Office, and may require them, before being recognized as representatives of applicants or other persons, to show that they are of good moral character and reputation and are possessed of the necessary qualifications to render to applicants or other persons valuable service, advice, and assistance in the presentation or prosecution of their applications or other business before the Office;"],[2,"(E) shall recognize the public interest in continuing to safeguard broad access to the United States patent system through the reduced fee structure for small entities under section 41(h)(1);"],[2,"(F) provide for the development of a performance-based process that includes quantitative and qualitative measures and standards for evaluating cost-effectiveness and is consistent with the principles of impartiality and competitiveness; and"],[2,"(G) may, subject to any conditions prescribed by the Director and at the request of the patent applicant, provide for prioritization of examination of applications for products, processes, or technologies that are important to the national economy or national competitiveness without recovering the aggregate extra cost of providing such prioritization, notwithstanding section 41 or any other provision of law;"],[1,"(3) may acquire, construct, purchase, lease, hold, manage, operate, improve, alter, and renovate any real, personal, or mixed property, or any interest therein, as it considers necessary to carry out its functions;"],[1,"(4)(A) may make such purchases, contracts for the construction, maintenance, or management and operation of facilities, and contracts for supplies or services, without regard to the provisions of subtitle I and chapter 33 of title 40, division C (except sections 3302, 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41, and the McKinney-Vento Homeless Assistance Act (42 U.S.C. 11301 et seq.); and"],[1,"(B) may enter into and perform such purchases and contracts for printing services, including the process of composition, platemaking, presswork, silk screen processes, binding, microform, and the products of such processes, as it considers necessary to carry out the functions of the Office, without regard to sections 501 through 517 and 1101 through 1123 of title 44;"],[1,"(5) may use, with their consent, services, equipment, personnel, and facilities of other departments, agencies, and instrumentalities of the Federal Government, on a reimbursable basis, and cooperate with such other departments, agencies, and instrumentalities in the establishment and use of services, equipment, and facilities of the Office;"],[1,"(6) may, when the Director determines that it is practicable, efficient, and cost-effective to do so, use, with the consent of the United States and the agency, instrumentality, Patent and Trademark Office, or international organization concerned, the services, records, facilities, or personnel of any State or local government agency or instrumentality or foreign patent and trademark office or international organization to perform functions on its behalf;"],[1,"(7) may retain and use all of its revenues and receipts, including revenues from the sale, lease, or disposal of any real, personal, or mixed property, or any interest therein, of the Office;"],[1,"(8) shall advise the President, through the Secretary of Commerce, on national and certain international intellectual property policy issues;"],[1,"(9) shall advise Federal departments and agencies on matters of intellectual property policy in the United States and intellectual property protection in other countries;"],[1,"(10) shall provide guidance, as appropriate, with respect to proposals by agencies to assist foreign governments and international intergovernmental organizations on matters of intellectual property protection;"],[1,"(11) may conduct programs, studies, or exchanges of items or services regarding domestic and international intellectual property law and the effectiveness of intellectual property protection domestically and throughout the world, and the Office is authorized to expend funds to cover the subsistence expenses and travel-related expenses, including per diem, lodging costs, and transportation costs, of persons attending such programs who are not Federal employees;"],[1,"(12)(A) shall advise the Secretary of Commerce on programs and studies relating to intellectual property policy that are conducted, or authorized to be conducted, cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) may conduct programs and studies described in subparagraph (A); and"],[1,"(13)(A) in coordination with the Department of State, may conduct programs and studies cooperatively with foreign intellectual property offices and international intergovernmental organizations; and"],[1,"(B) with the concurrence of the Secretary of State, may authorize the transfer of not to exceed $100,000 in any year to the Department of State for the purpose of making special payments to international intergovernmental organizations for studies and programs for advancing international cooperation concerning patents, trademarks, and other matters."],[0,"(c) Clarification of Specific Powers.—(1) The special payments under subsection (b)(13)(B) shall be in addition to any other payments or contributions to international organizations described in subsection (b)(13)(B) and shall not be subject to any limitations imposed by law on the amounts of such other payments or contributions by the United States Government."],[0,"(2) Nothing in subsection (b) shall derogate from the duties of the Secretary of State or from the duties of the United States Trade Representative as set forth in section 141 of the Trade Act of 1974 (19 U.S.C. 2171)."],[0,"(3) Nothing in subsection (b) shall derogate from the duties and functions of the Register of Copyrights or otherwise alter current authorities relating to copyright matters."],[0,"(4) In exercising the Director's powers under paragraphs (3) and (4)(A) of subsection (b), the Director shall consult with the Administrator of General Services."],[0,"(5) In exercising the Director's powers and duties under this section, the Director shall consult with the Register of Copyrights on all copyright and related matters."],[0,"(d) Construction.—Nothing in this section shall be construed to nullify, void, cancel, or interrupt any pending request-for-proposal let or contract issued by the General Services Administration for the specific purpose of relocating or leasing space to the United States Patent and Trademark Office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/2?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4"},"q":[{"src":"argument","who":"Mr. Taylor","text":"But what's so unique about this clause is there are a whole lot other -- there are other provisions of the Lanham Act in Section 2 that deal with the hypothetical that you just gave --"},{"src":"argument","who":"Mr. Taylor","text":"Well, so there -- I think there is a separate provision of Section 2 that deals with that, Justice Gorsuch. So -- so, if you look at subsection (e), I think it's the fourth one, marks that are primarily merely a surname are barred from registration."}]},{"t":"reg","label":"37 C.F.R. § 2.142","url":"https://www.ecfr.gov/current/title-37/section-2.142","by":{"0":"6"}},{"t":"case","label":"44 Liquormart v. Rhode Island","cite":"517 U.S. 484","y":1996,"id":"1995/94-1140","sc":1,"by":{"1":"28"}},{"t":"case","label":"Agency for International Development v. Alliance for Open Society International, Inc.","cite":"570 U.S. 205","y":2013,"id":"2012/12-10","sc":1,"by":{"1":"38","2":"5"},"q":[{"src":"brief","b":2,"text":"to regulate speech outside the contours of the program itself.","cite":"570 U.S. 205, 214-215"}]},{"t":"case","label":"American Steel Foundries v. Robertson","cite":"269 U.S. 372","y":1926,"id":"scdb/1925-212","sc":1,"by":{"1":"4"},"q":[{"src":"brief","b":1,"text":"as to be likely to produce confusion,","cite":"269 U.S. 372, 381"}]},{"t":"case","label":"Barr v. American Association of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"by":{"1":"19, 21, 26, 27"},"q":[{"src":"brief","b":1,"text":"That description applies to a law that singles out specific subject matter for differential treatment.","cite":"140 S. Ct. 2335, 2346"},{"src":"brief","b":1,"text":"That is about as contentbased as it gets.","cite":"140 S. Ct. at 2346"}]},{"t":"case","label":"Board of Regents of University of Wisconsin System v. Southworth","cite":"529 U.S. 217","y":2000,"id":"1999/98-1189","sc":1,"by":{"1":"41"}},{"t":"case","label":"Central Hudson Gas & Electric Corp. v. Public Service Commission of New York","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"by":{"1":"12, 16, 33, 34","2":"13"}},{"t":"case","label":"-v- City of Austin, Texas v. Reagan National Advertising of Austin, LLC","cite":"142 S. Ct. 1464","y":2022,"id":"2021/20-1029","sc":1,"by":{"1":"19, 20"},"q":[{"src":"brief","b":1,"text":"discriminate[s] based on the topic discussed or the idea or message expressed.","cite":"142 S. Ct. 1464, 1474"},{"src":"brief","b":1,"text":"single out [a] topic or subject matter for differential treatment.","cite":"142 S. Ct. at 1472"}]},{"t":"case","label":"Edenfield v. Fane","cite":"507 U.S. 761","y":1993,"id":"1992/91-1594","sc":1,"by":{"1":"28, 29"},"q":[{"src":"brief","b":1,"text":"the harms it recites are real and that its restriction will in fact alleviate them to a material degree.","cite":"507 U.S. 761, 771"},{"src":"brief","b":1,"text":"turn away if it appears that the [government’s] stated interests are not -30- the actual interests served by the restriction.","cite":"507 U.S. at 768"}]},{"t":"case","label":"Erie Railroad Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"by":{"1":"8"}},{"t":"case","label":"Friedman v. City of Highland Park, Illinois","cite":"784 F.3d 406","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/406/","by":{"1":"44"},"q":[{"src":"brief","b":1,"text":"a law’s existence [could] be the source of its own constitutional validity,","cite":"784 F.3d 406, 409"}]},{"t":"case","label":"Haelan Labratory, Inc. v. Topps Chewing Gum, Inc.","cite":"202 F.2d 866","y":1953,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/202/866/","by":{"1":"30"}},{"t":"case","label":"Healy v. James","cite":"408 U.S. 169","y":1972,"id":"1971/71-452","sc":1,"by":{"1":"41"}},{"t":"case","label":"Heffron v. International Society for Krishna Consciousness, Inc.","cite":"452 U.S. 640","y":1981,"id":"1980/80-795","sc":1,"by":{"1":"32"}},{"t":"case","label":"Hill v. Colorado","cite":"530 U.S. 703","y":2000,"id":"1999/98-1856","sc":1,"by":{"1":"21"}},{"t":"case","label":"-vi- Hoffman v. Capital Cities/ABC, Inc.","cite":"255 F.3d 1180","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/255/1180/","by":{"1":"32"}},{"t":"case","label":"Hustler Magazine, Inc. v. Falwell","cite":"485 U.S. 46","y":1988,"id":"1987/86-1278","sc":1,"by":{"1":"23"}},{"t":"case","label":"Ibanez v. Florida Department of Business & Professional Regulation, Board of Accountancy","cite":"512 U.S. 136","y":1994,"id":"1993/93-639","sc":1,"by":{"1":"27"}},{"t":"case","label":"Minnesota Voters Alliance v. Mansky","cite":"138 S. Ct. 1876","y":2018,"id":"2017/16-1435","sc":1,"by":{"1":"39"}},{"t":"case","label":"-vii- National Institute of Family & Life Advocates v. Becerra","cite":"138 S. Ct. 2361","y":2018,"id":"2017/16-1140","sc":1,"by":{"1":"39, 40","2":"18"},"q":[{"src":"brief","b":1,"text":"has the burden to prove that the [law] is neither unjustified nor unduly burdensome.","cite":"138 S. Ct. at 2377"},{"src":"brief","b":1,"text":"need not decide whether the [reasonableness] standard applies.","cite":"138 S. Ct. at 2376"}]},{"t":"case","label":"Pitt News v. Pappert","cite":"379 F.3d 96","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/379/96/","by":{"1":"42"}},{"t":"case","label":"Qualitex Co. v. Jacobson Products Co.","cite":"514 U.S. 159","y":1995,"id":"1994/93-1577","sc":1,"by":{"1":"5"},"q":[{"src":"brief","b":1,"text":"almost anything at all that is capable of carrying meaning","cite":"514 U.S. 159, 162"}]},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"by":{"1":"24, 40"},"q":[{"src":"brief","b":1,"text":"exception for content discrimination that does not threaten censorship of ideas,","cite":"505 U.S. 377, 393"},{"src":"brief","b":1,"text":"content discrimination that does not threaten censorship of ideas,","cite":"505 U.S. at 393"},{"src":"opinion","who":"Justice Kavanaugh, concurring in part","text":"is that content discrimination `raises the specter that the Government may effectively drive certain ideas or viewpoints from the marketplace.'","cite":"505 U. S. 377, 387"}]},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"by":{"1":"21","2":"13"}},{"t":"case","label":"Rogers v. Grimaldi","cite":"875 F.2d 994","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/875/994/","by":{"1":"32"}},{"t":"case","label":"Simon & Schuster, Inc. v. Members of New York State Crime Victims Board","cite":"502 U.S. 105","y":1991,"id":"1991/90-1059","sc":1,"by":{"1":"23, 26, 42","2":"4"},"q":[{"src":"brief","b":1,"text":"burden on speakers because of the content of their speech.","cite":"502 U.S. at 115"}]},{"t":"case","label":"Snyder v. Phelps","cite":"562 U.S. 443","y":2011,"id":"2010/09-751","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"Indeed, the point of all speech protection is to shield just those choices -24- of content that in someone’s eyes are misguided, or even hurtful.","cite":"562 U.S. 443, 458"}]},{"t":"case","label":"-viii- Sorrell v. IMS Health Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"by":{"1":"13, 14, 15, 17, 19, 21, 22, 25, 26, 27, 28, 30, 32, 33, 34, 41, 42","2":"13"},"q":[{"src":"brief","b":1,"text":"is sufficient to justify application of heightened scrutiny.","cite":"564 U.S. at 571"},{"src":"brief","b":1,"text":"content-based burdens must satisfy the same rigorous scrutiny as its contentbased bans.","cite":"564 U.S. at 565"}]},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"by":{"1":"23"}},{"t":"case","label":"Turner Broadcasting System, Inc. v. FCC","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"by":{"1":"27"}},{"t":"case","label":"U.S. Patent & Trademark Office v. Booking.com B.V.","cite":"140 S. Ct. 2298","y":2020,"id":"2019/19-46","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"A competitor’s use does not infringe a mark unless it is likely to confuse consumers,","cite":"140 S. Ct. 2298, 2307"}]},{"t":"case","label":"United States v. Kokinda","cite":"497 U.S. 720","y":1990,"id":"1989/88-2031","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"The significance of the governmental interest must be -38- assessed in light of the characteristic nature and function of the particular forum involved.","cite":"497 U.S. 720, 732"}]},{"t":"case","label":"United States v. Playboy Entertainment Group, Inc.","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"by":{"1":"23, 26, 42","2":"3, 4"},"q":[{"src":"brief","b":1,"text":"Where the designed benefit of a content-based speech restriction is to shield the sensibilities of listeners, the general rule is that the right of expression prevails.","cite":"529 U.S. 803, 813"},{"src":"brief","b":1,"text":"When the purpose and design of a statute is to regulate speech by reason of its content, special consideration or latitude is not accorded to the Government merely because the law can somehow be described as a burden rather than outright suppression.","cite":"529 U.S. at 826"}]},{"t":"case","label":"White Coat Waste Project v. Greater Richmond Transit Co.","cite":"35 F.4th 179","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/35/179/","by":{"1":"37, 39"},"q":[{"src":"brief","b":1,"text":"Reasonableness demands more than a rational basis.","cite":"35 F.4th 179, 198"},{"src":"brief","b":1,"text":"even a reasonable end must not be pursued by unreasonable means.","cite":"35 F.4th at 199"}]},{"t":"case","label":"White v. Samsung Electronics America, Inc.","cite":"989 F.2d 1512","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/989/1512/","by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"The last thing we need, the last thing the First Amendment will tolerate, is a law that lets public figures keep people from mocking them.","cite":"989 F.2d 1512, 1519"}]},{"t":"case","label":"Zacchini v. Scripps-Howard Broadcasting Co.","cite":"433 U.S. 562","y":1977,"id":"1976/76-577","sc":1,"by":{"1":"10, 29, 32"}},{"t":"case","label":"Zauderer v. Office of Disciplinary Counsel of Supreme Court of Ohio","cite":"471 U.S. 626","y":1985,"id":"1984/83-2166","sc":1,"by":{"1":"35, 36, 39","2":"18"},"q":[{"src":"brief","b":1,"text":"may, under some circumstances, be deceptive","cite":"471 U.S. 626, 649"},{"src":"brief","b":1,"text":"truthful -36- and nondeceptive advertising simply to spare itself the trouble of distinguishing such advertising from false or deceptive advertising.","cite":"471 U.S. at 646"}]},{"t":"case","label":"Elena Kagan, The Changing Faces of First Amendment Neutrality: R.A.V. v. St. Paul, Rust v. Sullivan, & the Problem of Content-Based Underinclusion","cite":"1992 Sup. Ct. Rev. 29","y":1992,"url":"https://www.courtlistener.com/c/Sup.%20Ct.%20Rev./1992/29/","by":{"1":"41"}},{"t":"case","label":"City of Renton v. Playtime Theatres, Inc.","cite":"475 U.S. 41","y":1986,"id":"1985/84-1360","sc":1,"by":{"2":"8"}},{"t":"case","label":"FCC v. Beach Commc’ns, Inc.","cite":"508 U.S. 307","y":1993,"id":"1992/92-603","sc":1,"by":{"2":"19, 22"}},{"t":"case","label":"Reed v. Bakers Eng’g & Equip. Co.","cite":"100 U.S.P.Q. 196","y":1954,"court":"P.T.O.","url":"https://www.courtlistener.com/c/U.S.P.Q./100/196/","by":{"2":"21"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"by":{"2":"8, 14"},"q":[{"src":"brief","b":2,"text":"[w]hat motivates one legislator to make a speech about a statute is not necessarily what motivates scores of others to enact it.","cite":"391 U.S. 367, 384"},{"src":"brief","b":2,"text":"made a ‘wiser’ speech about it.","cite":"391 U.S. at 384"}]},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"by":{"2":"10"}},{"t":"usc","label":"15 U.S.C. § 1058","url":"https://www.law.cornell.edu/uscode/text/15/1058","by":{"2":"6"}}]};